using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using Object=UnityEngine.Object;
public static class SawAssemblySetup {
 const string Root="Assets/Recovery/M6";
 static Material wood,steel; static StringBuilder report;
 public static void Run(){
 var scene=EditorSceneManager.OpenScene("Assets/Recovery/Scenes/School_Test.unity");
 if(GameObject.Find("M6 Saw Assembly"))throw new Exception("Saw assembly already configured; refusing duplicate setup");
 if(!File.Exists("RecoveryReports/School_Test-before-saw.unity"))EditorSceneManager.SaveScene(scene,"RecoveryReports/School_Test-before-saw.unity",true);
 report=new StringBuilder();wood=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/Wood.mat");steel=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/DarkSteel.mat");
 var ingredients=new[]{Item("saw_blade"),Item("saw_handle"),Item("screws")};
 var saw=ScriptableObject.CreateInstance<ItemData>();saw.id="assembled_saw";saw.itemName="Cưa tay";saw.description="Cưa đã lắp hoàn chỉnh. Chọn cưa rồi giữ E tại đống gỗ chắn DoorBack.";saw.type=ItemType.PuzzleItem;saw.weight=.75f;saw.maxStack=1;
 var old=AssetDatabase.LoadAssetAtPath<ItemData>(Root+"/Items/assembled_saw.asset");if(old){Object.DestroyImmediate(saw);saw=old;}else AssetDatabase.CreateAsset(saw,Root+"/Items/assembled_saw.asset");
 var model=new GameObject("Cưa tay");
 for(int i=0;i<3;i++){var part=Object.Instantiate(ingredients[i].pickupPrefab.gameObject);foreach(var c in part.GetComponents<Collider>())Object.DestroyImmediate(c);Object.DestroyImmediate(part.GetComponent<Rigidbody>());Object.DestroyImmediate(part.GetComponent<PickupItem>());part.transform.SetParent(model.transform,false);part.transform.localPosition=Vector3.zero;var b=BoundsOf(part);part.transform.position-=b.center;if(i==1)part.transform.localPosition+=new Vector3(-.29f,.005f,0);if(i==2){part.transform.localScale*=.45f;part.transform.localPosition=new Vector3(-.205f,.018f,0);}}
 var mb=BoundsOf(model);var box=model.AddComponent<BoxCollider>();box.center=mb.center;box.size=Vector3.Max(mb.size,new Vector3(.01f,.035f,.01f));var body=model.AddComponent<Rigidbody>();body.mass=saw.weight;body.isKinematic=true;var pickup=model.AddComponent<PickupItem>();pickup.item=saw;pickup.dropRadius=mb.extents.magnitude;model.layer=LayerMask.NameToLayer("Interactable");
 saw.pickupPrefab=PrefabUtility.SaveAsPrefabAsset(model,Root+"/Prefabs/AssembledSaw.prefab").GetComponent<PickupItem>();Render(model,"RecoveryReports/saw-model.png",new Vector3(.2f,.65f,-.4f),mb.center,512);Render(model,Root+"/Icons/assembled_saw.png",new Vector3(.2f,.65f,-.4f),mb.center,256);Object.DestroyImmediate(model);
 AssetDatabase.ImportAsset(Root+"/Icons/assembled_saw.png");var importer=(TextureImporter)AssetImporter.GetAtPath(Root+"/Icons/assembled_saw.png");importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.SaveAndReimport();saw.icon=AssetDatabase.LoadAssetAtPath<Sprite>(Root+"/Icons/assembled_saw.png");EditorUtility.SetDirty(saw);
 // Verified third-floor landing, to the right of DoorBack. Keep the stair route clear.
 var stationRoot=new GameObject("M6 Saw Assembly");stationRoot.transform.position=new Vector3(36.4f,14.95f,52.95f);stationRoot.transform.rotation=Quaternion.Euler(0,180,0);
 Box(stationRoot.transform,"Worn worktop",new Vector3(0,.82f,0),new Vector3(.84f,.065f,.46f),wood);
 foreach(float x in new[]{-.34f,.34f})foreach(float z in new[]{-.16f,.16f})Box(stationRoot.transform,"Bench leg",new Vector3(x,.4f,z),new Vector3(.06f,.8f,.06f),wood);
 Box(stationRoot.transform,"Steel brace",new Vector3(0,.23f,-.16f),new Vector3(.72f,.05f,.035f),steel);
 var station=stationRoot.AddComponent<SawAssemblyStation>();station.blade=ingredients[0];station.handle=ingredients[1];station.screws=ingredients[2];station.finishedSaw=saw;
 var output=new GameObject("Finished saw drop").transform;output.SetParent(stationRoot.transform,false);output.localPosition=new Vector3(0,1.03f,.01f);station.outputPoint=output;
 foreach(var c in stationRoot.GetComponentsInChildren<Collider>())c.gameObject.layer=LayerMask.NameToLayer("Interactable");
 Box(stationRoot.transform,"Recipe backing",new Vector3(0,1.24f,-.19f),new Vector3(.86f,.2f,.025f),steel).layer=LayerMask.NameToLayer("Interactable"); foreach(float x in new[]{-.33f,.33f})Box(stationRoot.transform,"Recipe support",new Vector3(x,1.02f,-.19f),new Vector3(.025f,.4f,.025f),steel); AddUI(station);
 FitRoofHeader();var door=ConfigureDoor();var barrier=new GameObject("M6 Saw Wood Barrier");barrier.transform.position=new Vector3(35.29f,14.95f,53.23f);
 var boards=new GameObject("Blocking timber");boards.transform.SetParent(barrier.transform,false);
 for(int i=0;i<5;i++){var plank=Box(boards.transform,"Old plank "+i,new Vector3(0,.3f+i*.48f,0),new Vector3(1.45f,.23f,.075f),wood);plank.transform.localRotation=Quaternion.Euler(0,0,i%2==0?9:-7);foreach(float x in new[]{-.57f,.57f}){var nail=Box(plank.transform,"Rust nail",new Vector3(x/1.45f,0,-.55f),new Vector3(.012f,.06f,.08f),steel);Object.DestroyImmediate(nail.GetComponent<Collider>());}}
 var action=barrier.AddComponent<HoldNoiseAction>();action.duration=18;action.loudness=.7f;var origin=new GameObject("Saw noise").transform;origin.SetParent(barrier.transform,false);origin.localPosition=new Vector3(0,1.3f,-.3f);action.noiseOrigin=origin;
 var gate=barrier.AddComponent<SawWoodBarrier>();gate.saw=saw;gate.boards=boards;gate.door=door;
 foreach(var c in boards.GetComponentsInChildren<Collider>())c.gameObject.layer=LayerMask.NameToLayer("Interactable");
 var font=AssetDatabase.LoadAssetAtPath<TMPro.TMP_FontAsset>("Assets/Recovery/Items/InteractionFont.asset");if(font){font.TryAddCharacters("Chọn lưỡi cưa tay cầm hoặc ốc vít rồi nhấn để lắp hoàn chỉnh gỗ chắn bộ phận đã được",out _);EditorUtility.SetDirty(font);foreach(var a in font.atlasTextures)EditorUtility.SetDirty(a);}
 Physics.SyncTransforms();report.AppendLine("Assembly="+stationRoot.transform.position+"; output="+output.position+"; instant selected-item installation, any order; 3 icons; silent.");report.AppendLine("Saw gate 18s, Action .7, selected saw required, progress retained, boards removed and physical door opened.");
 EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText("RecoveryReports/saw-setup.txt","PASS\n"+report);
 Preview();
 }
 static Door ConfigureDoor(){
 var root=GameObject.Find("Level/SchoolModel/Doors/DoorBack");if(!root||root.transform.position.y<14)throw new Exception("Third-floor DoorBack missing");
 var source=root.transform.Find("DoorBack_mesh").GetComponent<MeshFilter>();var original=source.sharedMesh;var sr=new SerializedObject(source.GetComponent<MeshRenderer>());int first=sr.FindProperty("m_StaticBatchInfo.firstSubMesh").intValue;if(sr.FindProperty("m_StaticBatchInfo.subMeshCount").intValue>0){var local=new Mesh();local.CombineMeshes(new[]{new CombineInstance{mesh=original,subMeshIndex=first,transform=source.transform.worldToLocalMatrix}},true,true);original=local;sr.FindProperty("m_StaticBatchInfo.firstSubMesh").intValue=0;sr.FindProperty("m_StaticBatchInfo.subMeshCount").intValue=0;sr.ApplyModifiedPropertiesWithoutUndo();GameObjectUtility.SetStaticEditorFlags(source.gameObject,0);}var verts=original.vertices;var world=verts.Select(v=>source.transform.TransformPoint(v)).ToArray();
 var leafMesh=Object.Instantiate(original);var frameMesh=Object.Instantiate(original);int count=0;
 for(int sm=0;sm<original.subMeshCount;sm++){var triangles=original.GetTriangles(sm);var leaf=new List<int>();var frame=new List<int>();for(int i=0;i<triangles.Length;i+=3){var center=(world[triangles[i]]+world[triangles[i+1]]+world[triangles[i+2]])/3;bool inside=Mathf.Abs(center.x-35.29f)<.665f&&center.y>14.99f&&center.y<17.745f;var list=inside?leaf:frame;list.Add(triangles[i]);list.Add(triangles[i+1]);list.Add(triangles[i+2]);if(inside)count++;}leafMesh.SetTriangles(leaf,sm);frameMesh.SetTriangles(frame,sm);}
 if(count<2)throw new Exception("Door leaf extraction failed: "+count);leafMesh.RecalculateBounds();frameMesh.RecalculateBounds();SaveMesh(leafMesh,Root+"/Models/RoofDoorLeaf.asset");SaveMesh(frameMesh,Root+"/Models/RoofDoorFrame.asset");source.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Root+"/Models/RoofDoorFrame.asset");
 foreach(var c in root.GetComponentsInChildren<Collider>())c.enabled=false;
 var leafRoot=new GameObject("Roof door leaf");leafRoot.transform.SetParent(root.transform,true);leafRoot.transform.position=new Vector3(35.29f,16.37f,53.56f);
 var visual=Object.Instantiate(source.gameObject,leafRoot.transform);visual.name="Moving metal leaf";visual.transform.SetPositionAndRotation(source.transform.position+Vector3.forward*.07f,source.transform.rotation);visual.transform.localScale=source.transform.lossyScale;visual.GetComponent<MeshFilter>().sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Root+"/Models/RoofDoorLeaf.asset");
 var box=leafRoot.AddComponent<BoxCollider>();box.size=new Vector3(1.29f,2.7f,.06f);leafRoot.layer=LayerMask.NameToLayer("Interactable");
 foreach(var t in visual.GetComponentsInChildren<Transform>())GameObjectUtility.SetStaticEditorFlags(t.gameObject,0);
 // Thin frame colliders replace the recovered solid volume across the whole doorway.
 foreach(float x in new[]{34.59f,35.99f}){var c=root.AddComponent<BoxCollider>();c.center=root.transform.InverseTransformPoint(new Vector3(x,16.38f,53.44f));c.size=new Vector3(.07f,2.88f,.20f);}
 var top=root.AddComponent<BoxCollider>();top.center=root.transform.InverseTransformPoint(new Vector3(35.29f,17.79f,53.44f));top.size=new Vector3(1.48f,.06f,.20f);
 var door=leafRoot.AddComponent<Door>();door.hingeOffset=new Vector3(-.645f,0,.04f);door.openAngle=-95;door.speed=95;door.requiredKeyId="";door.lockedPrompt="Cửa bị gỗ chắn — cần lắp cưa và cưa gỗ.";leafRoot.AddComponent<DoorNoise>();door.Initialize(true);door.Open(1);for(int i=0;i<120;i++)door.Tick(1f/60);report.AppendLine("Door sweep="+door.CurrentAngle+" blocker="+door.BlockingCollider+" triangles="+count);if(!door.IsFullyOpen)throw new Exception("Roof door swing blocked: "+door.BlockingCollider);door.SetImmediate(false);door.LockDoor();return door;
 }
 static void SaveMesh(Mesh m,string path){var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(m,old);Object.DestroyImmediate(m);}else AssetDatabase.CreateAsset(m,path);}
 static ItemData Item(string id)=>AssetDatabase.LoadAssetAtPath<ItemData>(Root+"/Items/"+id+".asset");
 static Bounds BoundsOf(GameObject go){var rs=go.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
 static GameObject Box(Transform parent,string name,Vector3 p,Vector3 scale,Material material){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=material;return g;}
 static Image Image(Transform parent,string name,Vector2 pos,Vector2 size,Color color){var g=new GameObject(name,typeof(RectTransform),typeof(CanvasRenderer),typeof(Image));g.transform.SetParent(parent,false);var r=g.GetComponent<RectTransform>();r.sizeDelta=size;r.anchoredPosition=pos;var image=g.GetComponent<Image>();image.color=color;image.raycastTarget=false;return image;}
 static void AddUI(SawAssemblyStation station){var g=new GameObject("Assembly recipe",typeof(RectTransform),typeof(Canvas));g.transform.SetParent(station.transform,false);g.transform.localPosition=new Vector3(0,1.24f,-.17f);g.transform.localRotation=Quaternion.Euler(0,180,0);g.transform.localScale=Vector3.one*.0015f;g.GetComponent<RectTransform>().sizeDelta=new Vector2(560,120);g.GetComponent<Canvas>().renderMode=RenderMode.WorldSpace;var ui=g.AddComponent<SawAssemblyUI>();ui.station=station;Image(g.transform,"Backing",Vector2.zero,new Vector2(560,120),new Color(.025f,.033f,.029f,.96f));for(int i=0;i<4;i++){float x=-210+i*140;if(i<3){ui.borders[i]=Image(g.transform,"Installed border "+i,new Vector2(x,0),new Vector2(96,96),Color.gray);ui.ingredientImages[i]=Image(g.transform,"Ingredient "+i,new Vector2(x,0),new Vector2(88,88),Color.white);ui.ingredientImages[i].preserveAspect=true;}else{ui.resultImage=Image(g.transform,"Completed saw",new Vector2(x,0),new Vector2(96,96),Color.white);ui.resultImage.preserveAspect=true;}if(i<3){float sx=x+70;Image(g.transform,"Symbol horizontal",new Vector2(sx,i==2?5:0),new Vector2(16,3),Color.gray);Image(g.transform,"Symbol other",new Vector2(sx,i==2?-5:0),i==2?new Vector2(16,3):new Vector2(3,16),Color.gray);}}ui.Refresh();}
 static void Render(GameObject go,string path,Vector3 offset,Vector3 target,int size){var prior=go?go.transform.position:Vector3.zero;if(go){go.transform.position+=Vector3.one*1000;target+=Vector3.one*1000;}var cam=new GameObject("Preview").AddComponent<Camera>();cam.transform.position=target+offset;cam.transform.LookAt(target);cam.nearClipPlane=.01f;if(go){cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.08f,.10f,.09f);}var l=new GameObject().AddComponent<Light>();l.type=LightType.Point;l.range=10;l.intensity=3;l.transform.position=cam.transform.position;var rt=new RenderTexture(size,size,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(size,size);tex.ReadPixels(new Rect(0,0,size,size),0,0);tex.Apply();File.WriteAllBytes(path,tex.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=null;Object.DestroyImmediate(tex);rt.Release();Object.DestroyImmediate(rt);Object.DestroyImmediate(l.gameObject);Object.DestroyImmediate(cam.gameObject);if(go)go.transform.position=prior;}
 static void FitRoofHeader(){foreach(var c in Object.FindObjectsByType<BoxCollider>()){if(c.name!="RoofExit"||Mathf.Abs(c.bounds.center.x-35.27f)>.1f||Mathf.Abs(c.bounds.center.z-53.49f)>.1f||c.bounds.size.y<2)continue;var b=c.bounds;float bottom=17.82f;var center=b.center;center.y=(bottom+b.max.y)*.5f;c.center=c.transform.InverseTransformPoint(center);var size=c.size;size.y=(b.max.y-bottom)/Mathf.Abs(c.transform.lossyScale.y);c.size=size;EditorUtility.SetDirty(c);}} public static void RepairAccess(){var scene=EditorSceneManager.OpenScene("Assets/Recovery/Scenes/School_Test.unity");FitRoofHeader();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.AppendAllText("RecoveryReports/saw-setup.txt","RoofExit solid collider fitted to header above 17.82m; actual frame and upper wall preserved.\n");} public static void RepairIcon(){EditorSceneManager.OpenScene("Assets/Recovery/Scenes/School_Test.unity");var saw=Item("assembled_saw");var model=Object.Instantiate(saw.pickupPrefab.gameObject);Render(model,Root+"/Icons/assembled_saw.png",new Vector3(.2f,.65f,-.4f),BoundsOf(model).center,256);Object.DestroyImmediate(model);AssetDatabase.ImportAsset(Root+"/Icons/assembled_saw.png");AssetDatabase.SaveAssets();} public static void Preview(){Render(null,"RecoveryReports/saw-station-preview.png",new Vector3(-.3f,.3f,-2.8f),new Vector3(35.8f,16.1f,53.3f),960);}
}
